insert into public.companies(id,name)values('c2000000-0000-4000-8000-000000000001','Working day payroll fixture');insert into public.user_company_roles(company_id,user_id,role)values('c2000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','Super Admin');
insert into public.company_settings(company_id,settings)values('c2000000-0000-4000-8000-000000000001','{"payroll":{"proration":"working","rounding":"half-up","currency":"INR"},"notifications":{"payroll":false,"leave":false}}');
insert into public.employees(id,company_id,employee_code,first_name,last_name,email,joining_date)values('c3000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000001','WORK01','Working','Employee','working@example.invalid','2026-09-10');
insert into public.employee_bank_details(company_id,employee_id,account_number,ifsc_code)values('c2000000-0000-4000-8000-000000000001','c3000000-0000-4000-8000-000000000001','1234567890','TEST0001234');
insert into public.employee_statutory_details(company_id,employee_id,pf_applicable,esi_applicable,pt_applicable,tds_applicable)values('c2000000-0000-4000-8000-000000000001','c3000000-0000-4000-8000-000000000001',false,false,false,false);
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);set local role authenticated;
do $$declare c uuid:='c2000000-0000-4000-8000-000000000001';e uuid:='c3000000-0000-4000-8000-000000000001';s uuid;r uuid;schedule uuid;rows jsonb;v integer;snapshot jsonb;begin
 s:=public.save_salary_structure(c,'{"name":"Working fixture salary","status":"Active","components":[{"code":"basic"}]}');
 perform public.assign_salary(c,e,s,'2026-09-10','{"basic":100001}');perform public.assign_salary(c,e,s,'2026-09-21','{"basic":200000}');
 select jsonb_agg(jsonb_build_object('employeeId',e,'date',d::date,'status',case when extract(dow from d)in(0,6)then 'Weekly Off'when d::date='2026-09-14'then 'Absent'when d::date='2026-09-15'then 'Half Day'else 'Present'end))into rows from generate_series('2026-09-10'::date,'2026-09-30'::date,interval '1 day')d;
 perform public.save_attendance(c,rows,'Reviewed actual register');perform public.finalize_attendance(c,'2026-09-01');
 if not exists(select 1 from jsonb_array_elements(public.validate_payroll(c,'2026-09-01')->'issues')x where x->>'check'='Working Day Calendar')then raise exception 'FAIL missing working calendar not blocked';end if;
 begin perform public.calculate_payroll(c,'2026-09-01');raise exception 'FAIL working payroll without calendar';exception when check_violation then null;end;
 schedule:=public.save_work_calendar(c,'{"kind":"schedule","effectiveFrom":"2026-09-01","workingDays":[1,2,3,4,5],"reviewReference":"Reviewed five day schedule"}');
 perform public.save_work_calendar(c,'{"kind":"holiday","date":"2026-09-02","name":"Reviewed fixture holiday","reviewReference":"Explicit holiday approval"}');
 if(public.validate_payroll(c,'2026-09-01')->>'blockingErrors')::integer<>0 then raise exception 'FAIL working calendar validation';end if;
 r:=public.calculate_payroll(c,'2026-09-01');select p.snapshot into snapshot from public.payroll_run_employees p where p.run_id=r;
 if(select gross_minor from public.payroll_run_employees where run_id=r)<>102381 or(snapshot->>'baselineGrossMinor')::bigint<>109524 then raise exception 'FAIL working day salary segmentation';end if;
 if(snapshot->>'prorationDays')::integer<>21 or(snapshot->>'paidDays')::numeric<>13.5 or snapshot->>'proration'<>'working'or jsonb_array_length(snapshot#>'{calendarBasis,schedules}')<>1 or jsonb_array_length(snapshot#>'{calendarBasis,holidays}')<>1 then raise exception 'FAIL working day immutable basis';end if;
 perform public.assign_salary(c,e,s,'2026-10-01','{"basic":100003}');
 select jsonb_agg(jsonb_build_object('employeeId',e,'date',d::date,'status',case when extract(dow from d)in(0,6)then 'Weekly Off'else 'Half Day'end))into rows from generate_series('2026-10-01'::date,'2026-10-31'::date,interval '1 day')d;
 perform public.save_attendance(c,rows,'Exact half month rounding fixture');perform public.finalize_attendance(c,'2026-10-01');perform public.calculate_payroll(c,'2026-10-01');
 if(select gross_minor from public.payroll_run_employees p join public.payroll_runs run on run.company_id=p.company_id and run.id=p.run_id where p.company_id=c and run.month='2026-10-01')<>50002 then raise exception 'FAIL exact half-paise working-month rounding';end if;
 perform public.save_versioned_company_settings(c,'{"payroll":{"proration":"working","rounding":"down","currency":"INR"},"notifications":{"payroll":false,"leave":false}}',1);perform public.calculate_payroll(c,'2026-10-01');
 if(select gross_minor from public.payroll_run_employees p join public.payroll_runs run on run.company_id=p.company_id and run.id=p.run_id where p.company_id=c and run.month='2026-10-01')<>50001 then raise exception 'FAIL exact half-paise round-down';end if;
 perform public.save_versioned_company_settings(c,'{"payroll":{"proration":"calendar","rounding":"half-up","currency":"INR"},"notifications":{"payroll":false,"leave":false}}',2);
 perform public.finalize_attendance(c,'2026-10-01',true,'Calendar rounding fixture');select jsonb_agg(jsonb_build_object('employeeId',e,'date',d::date,'status','Half Day'))into rows from generate_series('2026-10-01'::date,'2026-10-31'::date,interval '1 day')d;perform public.save_attendance(c,rows,'Calendar half-day rounding fixture',true);perform public.finalize_attendance(c,'2026-10-01');perform public.calculate_payroll(c,'2026-10-01');
 if(select gross_minor from public.payroll_run_employees p join public.payroll_runs run on run.company_id=p.company_id and run.id=p.run_id where p.company_id=c and run.month='2026-10-01')<>50002 then raise exception 'FAIL exact calendar half-paise rounding';end if;
 perform public.save_versioned_company_settings(c,'{"payroll":{"proration":"working","rounding":"half-up","currency":"INR"},"notifications":{"payroll":false,"leave":false}}',3);perform public.calculate_payroll(c,'2026-09-01');select p.snapshot into snapshot from public.payroll_run_employees p where p.run_id=r;

 select version into v from public.payroll_runs where id=r;
 perform public.retire_work_calendar(c,'schedule',schedule,1,'Reviewed roster correction');
 begin perform public.transition_payroll(c,'2026-09-01','approve',v);raise exception 'FAIL stale calendar approved';exception when serialization_failure or check_violation then null;end;
 if(select p.snapshot from public.payroll_run_employees p where p.run_id=r)is distinct from snapshot then raise exception 'FAIL old calendar snapshot changed';end if;
end $$;
reset role;
rollback;
